import{_ as e,c as a,a2 as p,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第四十五章 出家人和乞丐的区别","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/45第四十五章 出家人和乞丐的区别.md","filePath":"meditation/巴利文大藏经/45第四十五章 出家人和乞丐的区别.md"}'),_={name:"meditation/巴利文大藏经/45第四十五章 出家人和乞丐的区别.md"};function r(n,t,i,s,d,c){return o(),a("div",null,t[0]||(t[0]=[p('<h1 id="第四十五章-出家人和乞丐的区别" tabindex="-1">第四十五章 出家人和乞丐的区别 <a class="header-anchor" href="#第四十五章-出家人和乞丐的区别" aria-label="Permalink to &quot;第四十五章 出家人和乞丐的区别&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部7相应20经/乞食者经(婆罗门相应/有偈篇/祇夜)</p><p>有个时候，舍卫城里的一个乞丐来到佛陀的住所，他顶礼佛陀后，对佛陀说：“大德，我是一个乞丐，沿街乞讨为生，然而我看见你们出家人也是挨家挨户的讨饭吃，我与你们出家人有什么区别呢？我们都是向别人乞讨饭食，都是沿街乞讨，难道我也是出家人吗？”</p><p>佛陀说：“如果只是向别人乞讨饭食，那并不是出家人。还没有离开家庭，还有家人、财物等等的挂念和执着，就不是出家人。还有善法、恶法的挂念和执着，也不是出家人。多做善事能够为自己种植很多福德和功德，福德功德深厚的人，可以生到富贵之家，上生到天界享福，甚至于从生死轮回的煎熬和痛苦中永远的解脱出来，这些挂念和执着福德功德的人，不是出家人。多做恶事会为自己造下很多罪业，福德薄弱、罪业深重的人生到贫贱之家，下堕到地狱、饿鬼、畜生三恶道受苦，这些挂念和执着罪业的人，不是出家人。</p><p>世间什么样的人才是真正的出家人呢？那就是已经离开家庭，不再被亲人、财物等等事物事情所束缚和捆绑，不再挂念和执着世间一切的事物事情，出家修行的人。不再挂念和执着善恶、功德罪业，不再被善恶、功德罪业所束缚和捆绑，内心清净无染的人。修行的目的并不是为了获得解脱，也并不是为了从生死轮回的煎熬和痛苦中永远的解脱出来，无念无求，内心不再挂念和执着一切的念想，不被内心一切的念想束缚和捆绑的人，如果贪求证悟解脱的果位，那么就会被获得解脱的念想所污染和捆绑，不得解脱。这些已经开启智慧，不再挂念和执着世间一切事物事情，不再挂念和执着内心一切念想，出家修行的人，他们就是真正的出家人。</p><p>这时，佛陀说偈言：</p><p>「唯作乞他食，并非是比丘。</p><p>执持善恶法，并非是比丘。</p><p>功德罪业灭，依智慧于世。</p><p>以修梵行者，是名为比丘。」</p><p>佛陀说法后，这个乞丐立刻就跪在地上顶礼佛陀，他对佛陀说：“大德，您说的太好了，我之前一直都弄不清楚乞丐与出家人的区别，我现在明白了，感谢大德您为我慈悲的说法，请您让我皈依您，请您让我做您的在家修行弟子，我愿意受持您的戒律，我愿意按您的正法去修行。”</p><p>佛陀接受了这个乞丐的皈依。</p>',13)]))}const f=e(_,[["render",r]]);export{m as __pageData,f as default};
